import { DashboardShell } from "@/shared/components/dashboard-shell";
import { getVendorDashboard } from "@backend/bookings/queries";
import { requireRole } from "@backend/auth/session";
import { formatXaf } from "@/shared/lib/format";
import { WalletCards } from "lucide-react";
export const dynamic = "force-dynamic";
export default async function ServiceProviderPayoutsPage() { const session = await requireRole("service_provider"); const data = await getVendorDashboard(session.userId); const rows = data?.bookings ?? []; const protectedTotal = rows.reduce((sum, { escrow }) => sum + (["held", "release_scheduled"].includes(escrow?.status ?? "") ? escrow?.amount ?? 0 : 0), 0); return <DashboardShell role="service_provider" name={session.fullName} active="Payouts"><p className="eyebrow text-berry">Payouts</p><h1 className="display mt-2 text-4xl font-semibold">Protected revenue.</h1><section className="mt-8 max-w-2xl rounded-[22px] bg-forest p-7 text-white"><WalletCards className="text-marigold"/><p className="mono mt-6 text-3xl font-bold">{formatXaf(protectedTotal)}</p><p className="mt-2 text-sm text-white/55">Held until organiser confirmation, automatic release, or an admin decision.</p></section><div className="mt-6 max-w-2xl divide-y divide-ink/10 rounded-[22px] border border-ink/10 bg-white p-5">{rows.length ? rows.map(({ booking, escrow }) => <div key={booking.id} className="flex justify-between gap-4 py-4"><div><p className="mono text-xs font-bold">{booking.reference}</p><p className="mt-1 text-[10px] capitalize text-ink/45">{escrow?.status.replaceAll("_", " ") ?? "Awaiting payment"}</p></div><p className="mono text-xs font-bold">{formatXaf(escrow?.amount ?? booking.fundedAmount)}</p></div>) : <p className="py-6 text-sm text-ink/50">No payout activity yet.</p>}</div></DashboardShell>; }
